// Checkout conversion module - ensures paidEvents increment on successful payment
const { logEvent } = require('./eventLogger');

async function processCheckout(session) {
  // Validate session
  if (!session || !session.paymentConfirmed) {
    logEvent('checkout_failed', { reason: 'payment_not_confirmed' });
    return { success: false };
  }
  // Increment paidEvents
  await logEvent('paid_event', { amount: session.amount, currency: session.currency });
  return { success: true };
}

module.exports = { processCheckout };
